/* ---------- page chrome (mobile first) ---------- */
.top{position:sticky;top:0;z-index:50;background:rgba(14,10,7,.8);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,220,170,.08)}
.top-in{max-width:1240px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px}
.brand{display:flex;align-items:center;gap:10px;min-width:0}
.logo{flex:none;width:34px;height:34px;border-radius:10px;background:linear-gradient(140deg,#ffd27a,#e98a3b);display:grid;place-items:center;box-shadow:0 4px 14px rgba(233,138,59,.35)}
.logo i{position:relative;width:14px;height:14px;background:#fff;transform:rotate(45deg) translate(2px,2px);border-radius:2px}
.logo i::before,.logo i::after{content:"";position:absolute;width:14px;height:14px;background:#fff;border-radius:50%}
.logo i::before{left:-7px;top:0}.logo i::after{left:0;top:-7px}
.wordmark{font-size:19px;font-weight:800;letter-spacing:-.3px;color:#fff4e2}
.wordmark b{color:var(--gold);font-weight:800}
.brand .sep{display:none;width:1px;height:22px;background:#4a3726}
.brand .sub{display:none;font-size:13px;color:var(--muted);white-space:nowrap}
.hr{display:flex;align-items:center;gap:8px}
.live{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;color:#cfe9d8;background:rgba(34,197,94,.10);border:1px solid rgba(74,222,128,.28);border-radius:999px;padding:5px 10px;white-space:nowrap}
.live i{width:7px;height:7px;border-radius:50%;background:#4ade80;box-shadow:0 0 8px #4ade80;animation:pulse 1.8s ease-in-out infinite}
@keyframes pulse{50%{opacity:.35}}
.clock{font-variant-numeric:tabular-nums;font-size:12.5px;background:rgba(255,240,220,.05);border:1px solid rgba(255,220,170,.12);border-radius:999px;padding:5px 11px;white-space:nowrap}
.clock b{display:none;color:var(--gold);font-weight:700;margin-right:6px}
main{max-width:1240px;margin:0 auto;padding:18px 12px 0;display:grid;gap:28px}
.stage-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}
.eyebrow{display:inline-block;font-size:11px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--gold);margin-bottom:4px}
.stage-head h1{font-size:20px;font-weight:750;letter-spacing:-.2px;line-height:1.2;color:#fff2de}
.stage-head p{font-size:13px;line-height:1.45;color:var(--muted);margin-top:4px}
.btn{font:600 13px system-ui,sans-serif;color:#1c130b;background:linear-gradient(180deg,#ffd48a,#e9a54b);border:0;border-radius:10px;padding:8px 14px;cursor:pointer;box-shadow:0 4px 14px rgba(233,165,75,.3);white-space:nowrap}
.btn:active{transform:translateY(1px)}
.fitwrap{position:relative;width:100%;overflow:hidden;border-radius:18px;box-shadow:0 24px 60px rgba(0,0,0,.55),0 0 0 1px rgba(255,220,170,.10)}
.fitwrap.zoomed{cursor:grab;touch-action:none}
.fitwrap.dragging{cursor:grabbing}
.scenebox{position:absolute;left:0;top:0;width:1200px;height:780px;transform-origin:0 0}
.legend{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:14px}
.legend span{display:inline-flex;align-items:center;gap:7px;font-size:12px;color:#d9c7b0;background:rgba(255,240,220,.04);border:1px solid rgba(255,220,170,.10);border-radius:999px;padding:5px 11px}
.legend i{width:8px;height:8px;border-radius:50%;background:var(--k);box-shadow:0 0 8px var(--k)}
.hint{font-size:12px;color:#8e7c69;text-align:center;margin-top:10px}
.gcard{position:relative;padding:14px;border-radius:22px;background:linear-gradient(160deg,rgba(255,236,210,.08),rgba(255,236,210,.02) 45%,rgba(255,236,210,.05));border:1px solid rgba(255,220,170,.14);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 24px 60px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,240,220,.10)}
.gcard-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:2px 2px 12px}
.gcard-title{display:flex;align-items:center;gap:10px}
.gcard h2{font-size:17px;font-weight:750;color:#fff2de}
.badge-live{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;letter-spacing:.3px;color:#bbf7d0;background:rgba(34,197,94,.12);border:1px solid rgba(74,222,128,.3);border-radius:999px;padding:3px 9px}
.badge-live i{position:relative;display:block;width:7px;height:7px;border-radius:50%;background:#4ade80}
.badge-live i::after{content:"";position:absolute;left:0;top:0;width:100%;height:100%;border-radius:50%;background:#4ade80;animation:ping 1.6s cubic-bezier(0,0,.2,1) infinite}
@keyframes ping{75%,100%{transform:scale(2.6);opacity:0}}
.gcard-link{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;color:var(--gold);text-decoration:none;padding:7px 12px;border-radius:10px;border:1px solid rgba(255,200,97,.28);background:rgba(255,200,97,.06);white-space:nowrap}
.gcard-link:hover{background:rgba(255,200,97,.14)}
.gcard-link svg{width:13px;height:13px}
.gcard-frame{border-radius:16px;overflow:hidden;background:#0f0b08;border:1px solid rgba(255,220,170,.10)}
.gcard iframe{display:block;width:100%;height:55vh;min-height:340px;border:0;background:#0f0b08}
footer{max-width:1240px;margin:36px auto 0;padding:18px 12px 26px;border-top:1px solid rgba(255,220,170,.07);display:flex;justify-content:center;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px;color:#7d6c5b}
footer .dot{width:3px;height:3px;border-radius:50%;background:#5a4a3b}
@media(min-width:720px){
 .top-in{padding:12px 20px}.wordmark{font-size:21px}
 .brand .sep,.brand .sub{display:block}.clock b{display:inline}
 main{padding:28px 20px 0;gap:38px}
 .stage-head h1{font-size:24px}.stage-head p{font-size:14px}
 .fitwrap{border-radius:22px}
 .gcard{padding:20px}.gcard h2{font-size:19px}
 .gcard iframe{height:65vh}
}

