toolUseResult.content:
/* ---------- page chrome (mobile first) ---------- */
.top{position:sticky;top:0;z-index:50;background:rgba(14,10,7,.8);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,220,170,.08)}
.top-in{max-width:1240px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px}
.brand{display:flex;align-items:center;gap:10px;min-width:0}
.logo{flex:none;width:34px;height:34px;border-radius:10px;background:linear-gradient(140deg,#ffd27a,#e98a3b);display:grid;place-items:center;box-shadow:0 4px 14px rgba(233,138,59,.35)}
.logo i{position:relative;width:14px;height:14px;background:#fff;transform:rotate(45deg) translate(2px,2px);border-radius:2px}
.logo i::before,.logo i::after{content:"";position:absolute;width:14px;height:14px;background:#fff;border-radius:50%}
.logo i::before{left:-7px;top:0}.logo i::after{left:0;top:-7px}
.wordmark{font-size:19px;font-weight:800;letter-spacing:-.3px;color:#fff4e2}
.wordmark b{color:var(--gold);font-weight:800}
.brand .sep{display:none;width:1px;height:22px;background:#4a3726}
.brand .sub{display:none;font-size:13px;color:var(--muted);white-space:nowrap}
.hr{display:flex;align-items:center;gap:8px}
.live{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;color:#cfe9d8;background:rgba(34,197,94,.10);border:1px solid rgba(74,222,128,.28);border-radius:999px;padding:5px 10px;white-space:nowrap}
.live i{width:7px;height:7px;border-radius:50%;background:#4ade80;box-shadow:0 0 8px #4ade80;animation:pulse 1.8s ease-in-out infinite}
@keyframes pulse{50%{opacity:.35}}
.clock{font-variant-numeric:tabular-nums;font-size:12.5px;background:rgba(255,240,220,.05);border:1px solid rgba(255,220,170,.12);border-radius:999px;padding:5px 11px;white-space:nowrap}
.clock b{display:none;color:var(--gold);font-weight:700;margin-right:6px}
main{max-width:1240px;margin:0 auto;padding:18px 12px 0;display:grid;gap:28px}
.stage-head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}
.eyebrow{display:inline-block;font-size:11px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;color:var(--gold);margin-bottom:4px}
.stage-head h1{font-size:20px;font-weight:750;letter-spacing:-.2px;line-height:1.2;color:#fff2de}
.stage-head p{font-size:13px;line-height:1.45;color:var(--muted);margin-top:4px}
.btn{font:600 13px system-ui,sans-serif;color:#1c130b;background:linear-gradient(180deg,#ffd48a,#e9a54b);border:0;border-radius:10px;padding:8px 14px;cursor:pointer;box-shadow:0 4px 14px rgba(233,165,75,.3);white-space:nowrap}
.btn:active{transform:translateY(1px)}
.fitwrap{position:relative;width:100%;overflow:hidden;border-radius:18px;box-shadow:0 24px 60px rgba(0,0,0,.55),0 0 0 1px rgba(255,220,170,.10)}
.fitwrap.zoomed{cursor:grab;touch-action:none}
.fitwrap.dragging{cursor:grabbing}
.scenebox{position:absolute;left:0;top:0;width:1200px;height:780px;transform-origin:0 0}
.legend{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:14px}
.legend span{display:inline-flex;align-items:center;gap:7px;font-size:12px;color:#d9c7b0;background:rgba(255,240,220,.04);border:1px solid rgba(255,220,170,.10);border-radius:999px;padding:5px 11px}
.legend i{width:8px;height:8px;border-radius:50%;background:var(--k);box-shadow:0 0 8px var(--k)}
.hint{font-size:12px;color:#8e7c69;text-align:center;margin-top:10px}
.gcard{position:relative;padding:14px;border-radius:22px;background:linear-gradient(160deg,rgba(255,236,210,.08),rgba(255,236,210,.02) 45%,rgba(255,236,210,.05));border:1px solid rgba(255,220,170,.14);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 24px 60px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,240,220,.10)}
.gcard-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:2px 2px 12px}
.gcard-title{display:flex;align-items:center;gap:10px}
.gcard h2{font-size:17px;font-weight:750;color:#fff2de}
.badge-live{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;letter-spacing:.3px;color:#bbf7d0;background:rgba(34,197,94,.12);border:1px solid rgba(74,222,128,.3);border-radius:999px;padding:3px 9px}
.badge-live i{position:relative;display:block;width:7px;height:7px;border-radius:50%;background:#4ade80}
.badge-live i::after{content:"";position:absolute;left:0;top:0;width:100%;height:100%;border-radius:50%;background:#4ade80;animation:ping 1.6s cubic-bezier(0,0,.2,1) infinite}
@keyframes ping{75%,100%{transform:scale(2.6);opacity:0}}
.gcard-link{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;color:var(--gold);text-decoration:none;padding:7px 12px;border-radius:10px;border:1px solid rgba(255,200,97,.28);background:rgba(255,200,97,.06);white-space:nowrap}
.gcard-link:hover{background:rgba(255,200,97,.14)}
.gcard-link svg{width:13px;height:13px}
.gcard-frame{border-radius:16px;overflow:hidden;background:#0f0b08;border:1px solid rgba(255,220,170,.10)}
.gcard iframe{display:block;width:100%;height:55vh;min-height:340px;border:0;background:#0f0b08}
footer{max-width:1240px;margin:36px auto 0;padding:18px 12px 26px;border-top:1px solid rgba(255,220,170,.07);display:flex;justify-content:center;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px;color:#7d6c5b}
footer .dot{width:3px;height:3px;border-radius:50%;background:#5a4a3b}
@media(min-width:720px){
 .top-in{padding:12px 20px}.wordmark{font-size:21px}
 .brand .sep,.brand .sub{display:block}.clock b{display:inline}
 main{padding:28px 20px 0;gap:38px}
 .stage-head h1{font-size:24px}.stage-head p{font-size:14px}
 .fitwrap{border-radius:22px}
 .gcard{padding:20px}.gcard h2{font-size:19px}
 .gcard iframe{height:65vh}
}

input.content:
/* agents: chibi figures, billboard facing the camera */
.agent{left:0;top:0;width:0;height:0;transform-style:preserve-3d;will-change:transform}
.agent .ash{left:-22px;top:-9px;width:44px;height:18px;border-radius:50%;background:radial-gradient(closest-side,rgba(25,12,4,.62),rgba(25,12,4,.25) 60%,rgba(25,12,4,0));transform:translateZ(.4px)}
.agent.sit .ash{left:-26px;width:52px}
.agent.walk .ash{animation:shad .22s ease-in-out infinite alternate}
@keyframes shad{to{transform:translateZ(.4px) scale(.84)}}
.agent .ring{left:-30px;top:-15px;width:60px;height:30px;border-radius:50%;border:3px solid #ffd76a;box-shadow:0 0 16px 2px rgba(255,215,106,.85),inset 0 0 12px rgba(255,215,106,.55);opacity:0;transform:translateZ(.8px);transition:opacity .3s}
.agent.sel .ring{opacity:1;animation:ring 1.3s ease-in-out infinite}
@keyframes ring{50%{transform:translateZ(.8px) scale(1.14);box-shadow:0 0 26px 6px rgba(255,215,106,.9),inset 0 0 14px rgba(255,215,106,.6)}}
.agent.sel .bw{filter:drop-shadow(0 0 3px rgba(255,225,130,1)) drop-shadow(0 0 9px rgba(255,190,80,.75))}
.agent .fig{left:-28px;top:-100px;width:56px;height:100px;transform-origin:50% 100%;transform:rotateX(-90deg) scale(1.15);cursor:pointer}
.fig .hit{left:-12px;top:-8px;width:80px;height:112px;border-radius:30px}
.fig .bw,.fig .up{left:0;top:0;width:100%;height:100%}
.fig .leg{bottom:4px;width:10px;height:21px;border-radius:4px 4px 2px 2px;transform-origin:50% 2px;background:linear-gradient(90deg,rgba(255,255,255,.08),rgba(0,0,0,0) 40%,rgba(0,0,0,.24)),var(--p)}
.fig .leg::after{content:"";position:absolute;left:-2px;bottom:-4px;width:14px;height:7px;border-radius:7px 7px 3px 3px;background:linear-gradient(#3a302a,#15110e);box-shadow:inset 0 1px 0 rgba(255,255,255,.18)}
.fig .leg.l{left:17px}.fig .leg.r{left:29px}
.fig .torso{left:13px;bottom:21px;width:30px;height:28px;border-radius:13px 13px 7px 7px;background:linear-gradient(90deg,rgba(255,255,255,.16),rgba(255,255,255,0) 35%,rgba(0,0,0,0) 65%,rgba(0,0,0,.2)),var(--c);box-shadow:inset 0 -5px 0 rgba(0,0,0,.14)}
.fig .torso::before{content:"";position:absolute;left:10px;top:0;width:10px;height:8px;background:var(--sk);clip-path:polygon(0 0,100% 0,50% 100%)}
.fig .torso::after{content:"";position:absolute;left:14px;top:11px;width:2px;height:11px;border-radius:1px;background:rgba(0,0,0,.15)}
.fig .arm{bottom:25px;width:9px;height:23px;border-radius:5px;transform-origin:50% 4px;background:linear-gradient(90deg,rgba(255,255,255,.12),rgba(0,0,0,.18)),var(--c)}
.fig .arm::after{content:"";position:absolute;left:0;bottom:-4px;width:9px;height:9px;border-radius:50%;background:var(--sk);box-shadow:inset -1px -1px 0 rgba(0,0,0,.15)}
.fig .arm.l{left:6px}.fig .arm.r{left:41px}
.fig .neck{left:23px;bottom:46px;width:10px;height:6px;border-radius:3px;background:var(--sk);box-shadow:inset 0 2px 0 rgba(0,0,0,.14)}
.fig .head{left:8px;bottom:49px;width:40px;height:38px;border-radius:50% 50% 46% 46%/54% 54% 46% 46%;background:radial-gradient(circle at 38% 34%,rgba(255,255,255,.22),rgba(255,255,255,0) 55%),var(--sk);box-shadow:inset -4px -3px 0 rgba(0,0,0,.08)}
.fig .ear{top:16px;width:7px;height:10px;border-radius:50%;background:var(--sk);box-shadow:inset 0 0 0 2px rgba(0,0,0,.06)}
.fig .ear.l{left:-3px}.fig .ear.r{right:-3px}
.fig .hair{left:-2px;top:-4px;width:44px;height:17px;background:var(--hc);border-radius:22px 22px 8px 8px/20px 20px 8px 8px;box-shadow:inset 0 3px 0 rgba(255,255,255,.1)}
.fig .brow{top:14px;width:8px;height:2px;border-radius:2px;background:var(--hc);opacity:.85}
.fig .brow.l{left:9px}.fig .brow.r{left:23px}
.fig .eye{top:18px;width:6px;height:7px;border-radius:3px;background:radial-gradient(circle at 35% 30%,#fff 0 1.1px,#241812 1.5px);animation:blink 5s infinite;animation-delay:var(--bd)}
.fig .eye.l{left:10px}.fig .eye.r{left:24px}
.fig .mouth{left:16px;top:27px;width:8px;height:4px;border-bottom:2px solid #8a3b2e;border-radius:0 0 8px 8px}
.fig .blush{left:4px;top:25px;width:32px;height:5px;background:radial-gradient(circle at 8% 50%,rgba(240,110,100,.4) 0 2.5px,#0000 3.5px),radial-gradient(circle at 92% 50%,rgba(240,110,100,.4) 0 2.5px,#0000 3.5px)}
@keyframes blink{0%,94%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}
.h-long .hair::after{content:"";position:absolute;left:0;top:8px;width:44px;height:34px;border-radius:6px 6px 12px 12px;background:linear-gradient(90deg,var(--hc) 0 7px,#0000 7px 37px,var(--hc) 37px)}
.h-bun .hair::before{content:"";position:absolute;left:14px;top:-10px;width:16px;height:14px;border-radius:50%;background:var(--hc)}
.h-curly .hair{left:-5px;top:-8px;width:50px;height:22px;background:radial-gradient(circle at 16% 64%,var(--hc) 0 8px,#0000 8.5px),radial-gradient(circle at 34% 40%,var(--hc) 0 9px,#0000 9.5px),radial-gradient(circle at 50% 46%,var(--hc) 0 11px,#0000 11.5px),radial-gradient(circle at 66% 40%,var(--hc) 0 9px,#0000 9.5px),radial-gradient(circle at 84% 64%,var(--hc) 0 8px,#0000 8.5px);box-shadow:none}
.agent.back.h-curly .hair{background:var(--hc);left:-2px;width:44px}
.h-pony .hair::after{content:"";position:absolute;right:-8px;top:6px;width:11px;height:26px;border-radius:6px 6px 11px 11px;background:var(--hc)}
.h-bald .hair{left:6px;width:28px;height:7px;top:-1px;opacity:.7}
.a-glasses .head::after{content:"";position:absolute;left:6px;top:15px;width:28px;height:13px;background:radial-gradient(circle at 25% 50%,#0000 0 4px,#1c1c1c 4.3px 5.5px,#0000 5.8px),radial-gradient(circle at 75% 50%,#0000 0 4px,#1c1c1c 4.3px 5.5px,#0000 5.8px),linear-gradient(#1c1c1c,#1c1c1c) 50% 45%/6px 1.5px no-repeat}
.a-headset .head::before{content:"";position:absolute;left:-5px;top:-7px;width:50px;height:26px;border:3px solid #1f2937;border-bottom:0;border-radius:26px 26px 0 0;z-index:2}
.a-headset .head::after{content:"";position:absolute;left:-6px;top:14px;width:8px;height:12px;border-radius:4px;background:#111827;box-shadow:44px 0 0 #111827;z-index:2}
.a-beret .hair::before{content:"";position:absolute;left:-4px;top:-8px;width:48px;height:14px;border-radius:50% 60% 40% 40%;background:#b91c1c;transform:rotate(-8deg)}
.a-cap .hair::before{content:"";position:absolute;left:-1px;top:-4px;width:46px;height:14px;border-radius:23px 23px 0 0;background:#1d4ed8}
.a-cap .hair::after{content:"";position:absolute;left:28px;top:8px;width:24px;height:5px;border-radius:3px;background:#1e40af}
.crown{left:17px;bottom:84px;width:22px;height:14px;background:linear-gradient(180deg,#fff2a8,#f5b82e 55%,#b7791f);clip-path:polygon(0 100%,0 25%,22% 60%,50% 0,78% 60%,100% 25%,100% 100%);filter:drop-shadow(0 0 3px rgba(255,200,60,.9))}
.crown::after{content:"";position:absolute;left:9px;bottom:3px;width:4px;height:4px;border-radius:50%;background:#e11d48}
.agent.back .eye,.agent.back .mouth,.agent.back .blush,.agent.back .brow,.agent.back .head::after{display:none}
.agent.back .hair{height:calc(100% + 4px);border-radius:22px 22px 16px 16px}
.agent.flip .bw{transform:scaleX(-1)}
/* walking: alternate steps, foot lifts on the pass, arms counter swing */
.agent.walk .leg.l{animation:stepL .44s linear infinite}
.agent.walk .leg.r{animation:stepR .44s linear infinite}
.agent.walk .arm.l{animation:armA .44s ease-in-out infinite}
.agent.walk .arm.r{animation:armB .44s ease-in-out infinite}
.agent.walk .up{animation:bob .22s ease-in-out infinite alternate}
@keyframes stepL{0%,100%{transform:rotate(24deg)}25%{transform:translateY(-3px) rotate(0)}50%{transform:rotate(-24deg)}75%{transform:rotate(0)}}
@keyframes stepR{0%,100%{transform:rotate(-24deg)}25%{transform:rotate(0)}50%{transform:rotate(24deg)}75%{transform:translateY(-3px) rotate(0)}}
@keyframes armA{0%,100%{transform:rotate(-22deg)}50%{transform:rotate(22deg)}}
@keyframes armB{0%,100%{transform:rotate(22deg)}50%{transform:rotate(-22deg)}}
@keyframes bob{from{transform:translateY(0)}to{transform:translateY(-2px)}}
.agent.idle .up{animation:breathe 3s ease-in-out infinite}
@keyframes breathe{50%{transform:translateY(-1px)}}
/* working: seated, hands on the keyboard, gentle typing sway */
.agent.sit .leg{display:none}
.agent.sit .up{top:6px;animation:typeSway 1.6s ease-in-out infinite}
.agent.sit .arm{height:20px;bottom:24px;z-index:2}
.agent.sit .arm.l{animation:typeL .24s ease-in-out infinite alternate}
.agent.sit .arm.r{animation:typeR .24s .12s ease-in-out infinite alternate}
.agent.sit .head{animation:nod 5s ease-in-out infinite}
@keyframes typeSway{0%,50%,100%{transform:translate(0,0)}25%{transform:translate(.6px,.5px)}75%{transform:translate(-.6px,.5px)}}
@keyframes typeL{from{transform:rotate(-30deg) scaleY(.9)}to{transform:rotate(-40deg) scaleY(.84) translateY(1px)}}
@keyframes typeR{from{transform:rotate(30deg) scaleY(.9)}to{transform:rotate(40deg) scaleY(.84) translateY(1px)}}
@keyframes nod{0%,86%,100%{transform:translateY(0)}90%{transform:translateY(1px) rotate(3deg)}}
/* in a chat: stop and look at the visitor */
.agent.chatting .up,.agent.chatting .head,.agent.chatting .arm{animation:none}
.agent.chatting.sit .arm.l{transform:rotate(-16deg)}
.agent.chatting.sit .arm.r{transform:rotate(16deg)}
.hanc{left:27px;top:-6px;width:2px;height:2px}

