/* ---------- chat ---------- */
body.noscroll{overflow:hidden}
.chat{position:fixed;left:0;top:0;width:100%;height:100%;z-index:100;display:none;align-items:flex-end;justify-content:center;padding:0 8px 8px;background:rgba(8,5,3,.62);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.chat.open{display:flex;animation:fadeIn .2s ease-out}
.chat-dlg{position:relative;width:100%;max-width:460px;height:min(640px,92%);display:flex;flex-direction:column;border-radius:22px;overflow:hidden;background:linear-gradient(180deg,#2b1e14,#17100a);border:1px solid rgba(255,220,170,.16);box-shadow:0 30px 80px rgba(0,0,0,.6);animation:popUp .3s cubic-bezier(.2,.9,.3,1.15)}
@keyframes fadeIn{from{opacity:0}}
@keyframes popUp{from{opacity:0;transform:translateY(24px) scale(.97)}}
.chat-head{display:flex;align-items:center;gap:12px;padding:14px 14px 12px 16px;background:linear-gradient(180deg,rgba(255,200,120,.10),rgba(255,200,120,0));border-bottom:1px solid rgba(255,220,170,.10)}
.av{position:relative;flex:none;width:48px;height:48px;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 50% 30%,#4a3524,#24180f);box-shadow:0 0 0 2px var(--c),0 0 18px rgba(255,200,120,.25)}
.av i{position:absolute;display:block}
.av .av-body{left:9px;width:30px;bottom:-10px;height:22px;border-radius:14px 14px 0 0;background:var(--c)}
.av .av-head{left:12px;top:8px;width:24px;height:24px;border-radius:50%;background:var(--sk)}
.av .av-hair{left:-1px;top:-3px;width:26px;height:11px;border-radius:13px 13px 5px 5px;background:var(--hc)}
.av .av-eye{top:11px;width:3px;height:4px;border-radius:2px;background:#271b15}
.av .av-eye.l{left:7px}.av .av-eye.r{left:14px}
.av .av-mouth{left:9px;top:16px;width:6px;height:3px;border-bottom:2px solid #8a3b2e;border-radius:0 0 6px 6px}
.chat-who{flex:1;min-width:0}
.chat-who b{display:block;font-size:16px;color:#fff2de}
.chat-who span{display:block;font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chat-who em{display:flex;align-items:center;gap:6px;margin-top:3px;font-style:normal;font-size:11px;color:#86efac;white-space:nowrap;overflow:hidden}
.chat-who em i{flex:none;width:6px;height:6px;border-radius:50%;background:#4ade80;box-shadow:0 0 6px #4ade80}
.chat-who em span{font-size:11px;color:#86efac}
.chat-x{flex:none;width:38px;height:38px;border-radius:12px;border:1px solid rgba(255,220,170,.16);background:rgba(255,255,255,.04);color:#f6ecdf;font-size:22px;line-height:1;cursor:pointer}
.chat-x:hover{background:rgba(255,255,255,.1)}
.chat-msgs{flex:1;min-height:0;overflow-y:auto;padding:16px 14px;display:flex;flex-direction:column;gap:8px;overscroll-behavior:contain}
.msg{display:flex;max-width:84%;animation:msgIn .22s ease-out}
@keyframes msgIn{from{opacity:0;transform:translateY(6px)}}
.msg p{padding:9px 13px;border-radius:16px;font-size:14px;line-height:1.42;overflow-wrap:anywhere}
.msg.ag{align-self:flex-start}
.msg.ag p{background:#3a2a1d;color:#f6ecdf;border:1px solid rgba(255,220,170,.10);border-bottom-left-radius:5px}
.msg.me{align-self:flex-end}
.msg.me p{background:linear-gradient(180deg,#ffd48a,#e9a54b);color:#1c130b;border-bottom-right-radius:5px}
.typing p{display:flex;align-items:center;gap:4px;padding:10px 14px;color:#cdb89c;font-size:12.5px}
.typing span{margin-right:4px}
.typing i{display:block;width:6px;height:6px;border-radius:50%;background:#d9c3a5;animation:dot 1s ease-in-out infinite}
.typing i:nth-of-type(2){animation-delay:.15s}.typing i:nth-of-type(3){animation-delay:.3s}
@keyframes dot{0%,60%,100%{transform:translateY(0);opacity:.45}30%{transform:translateY(-4px);opacity:1}}
.chat-form{display:flex;gap:8px;padding:10px 12px calc(12px + env(safe-area-inset-bottom,0px));border-top:1px solid rgba(255,220,170,.1);background:rgba(0,0,0,.2)}
.chat-form input{flex:1;min-width:0;font:16px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#fff4e2;background:#120d09;border:1px solid #4a3726;border-radius:14px;padding:11px 14px;outline:none}
.chat-form input::placeholder{color:#8e7c69}
.chat-form input:focus{border-color:#e9a54b;box-shadow:0 0 0 3px rgba(233,165,75,.2)}
.chat-form button{flex:none;width:48px;border:0;border-radius:14px;background:linear-gradient(180deg,#ffd48a,#e9a54b);color:#1c130b;cursor:pointer;display:grid;place-items:center}
.chat-form button svg{width:20px;height:20px}
@media(min-width:720px){.chat{align-items:center;padding:24px}.chat-dlg{height:min(620px,86%)}}

