function buildAgent(a,i){
 var el=mk(world,'agent sit h-'+(a.hair||'short')+(a.acc?' a-'+a.acc:''));
 el.style.setProperty('--c',a.c);el.style.setProperty('--p',a.p);el.style.setProperty('--hc',a.hc);el.style.setProperty('--sk',a.sk);el.style.setProperty('--bd',(Math.random()*4).toFixed(2)+'s');
 el.innerHTML='<i class="ash"></i><i class="ring"></i><div class="fig" title="Conversar com '+a.n+'"><i class="hit"></i><div class="bw"><i class="leg l"></i><i class="leg r"></i><div class="up"><i class="arm l"></i><i class="arm r"></i><i class="torso"></i><i class="neck"></i><div class="head"><i class="ear l"></i><i class="ear r"></i><i class="hair"></i><i class="brow l"></i><i class="brow r"></i><i class="eye l"></i><i class="eye r"></i><i class="mouth"></i><i class="blush"></i></div>'+(a.acc==='crown'?'<i class="crown"></i>':'')+'<i class="hanc"></i></div></div></div>';
 a.el=el;a.anc=el.querySelector('.hanc');a.x=a.seat[0];a.y=a.seat[1];a.path=null;a.away=false;a.cur=a.work[0];a.st={k:'desk'};
 place(a);
 el.querySelector('.fig').addEventListener('click',function(ev){ev.stopPropagation();if(dragMoved){dragMoved=false;return}openChat(a)});
 var b=document.createElement('div');b.className='bub';hud.appendChild(b);a.bub=b;
}
function place(a){a.el.style.transform='translate3d('+a.x.toFixed(1)+'px,'+a.y.toFixed(1)+'px,0)'}
function pose(a,p){a.el.classList.remove('walk','sit','idle');a.el.classList.add(p);if(p!=='walk')a.el.classList.remove('back')}

