var HELLO=['Oi!','Olá!','Opa, oi!','Oi, tudo bem por aqui!'];
var GREET=['Oi! Agora estou {onde}, mas tenho um tempinho pra você.','Olá! Você me encontrou {onde}. Pode falar!','Oi, que bom te ver! Estou {onde} neste momento.','Olá! Chegou na hora certa, estou {onde}.'];
var GREET_DESK=['Por aqui: {cur}.','O que rolou agora: {cur}.','Última novidade: {cur}.'];
var NOW=['Neste momento estou {onde}.','Agora estou {onde}.','Você me pegou {onde}.','Por enquanto estou {onde}.'];
var NOW_DESK=['Agora estou {onde}, e a última foi: {cur}.','Estou {onde}. Por aqui: {cur}.','Tudo andando {onde}. Agora mesmo: {cur}.'];
var ORDER=['tchau','obg','faz','agora','cuidar','oi'];
var RX={
 tchau:/(tchau|\bate (mais|logo|amanha|breve|a proxima|ja)\b|\bfalou\b|\bflw\b|\bbye\b|boa noite|\bfui\b|vou nessa|to indo embora)/,
