};
var chatEl=$('chat'),chatMsgs=$('chatMsgs'),chatForm=$('chatForm'),chatIn=$('chatIn'),chatAv=$('chatAv');
var CHAT={a:null,token:0,chain:Promise.resolve(),back:null};
var HIST={};
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').trim()}
function atDesk(a){return !a.st||a.st.k==='desk'}
function estado(a){
 var s=a.st||{k:'desk'};
 if(s.k==='going')return s.host?'indo falar com '+s.host.n:s.poi.go;
 if(s.k==='there')return s.host?'conversando com '+s.host.n:s.poi.where;
 if(s.k==='back')return 'voltando pra minha mesa';
 return a.boss?'aqui na minha sala':(a.desk?'aqui na minha mesa':'na mesa grande do conteúdo');
}
function fill(a,s){return s.replace(/\{onde\}/g,estado(a)).replace(/\{cur\}/g,a.cur)}
// Random piece that is never the same as the previous one of that kind
function fresh(a,key,arr){a.lp=a.lp||{};var s,n=0;do{s=pick(arr)}while(arr.length>1&&s===a.lp[key]&&++n<12);a.lp[key]=s;return s}
function greet(a){
 var out,n=0;
 do{out=fill(a,fresh(a,'greet',GREET)+(atDesk(a)?' '+fresh(a,'greetd',GREET_DESK):''))}while(out===a.lastSaid&&++n<12);
 return a.lastSaid=out;
}
function reply(a,text){
 var t=norm(text),R=REP[a.id],cat='gen',out,n=0;
 for(var i=0;i<ORDER.length;i++)if(RX[ORDER[i]].test(t)){cat=ORDER[i];break}
 do{
  if(cat==='gen')out=fresh(a,'gen',R.gen)+' '+fresh(a,'gen2',R.gen2);
  else if(cat==='agora')out=fresh(a,'now',atDesk(a)?NOW_DESK:NOW)+' '+fresh(a,'agora',R.agora);
  else{out=fresh(a,cat,R[cat]);if(cat!=='oi'&&RX.oi.test(t))out=fresh(a,'hello',HELLO)+' '+out}
  out=fill(a,out);
 }while(out===a.lastSaid&&++n<12);
 return a.lastSaid=out;
}
function push(a,from,t){var h=HIST[a.id]=HIST[a.id]||[];h.push({f:from,t:t});if(h.length>6)h.splice(0,h.length-6)}
function bubble(f,t){var d=document.createElement('div');d.className='msg '+f;var p=document.createElement('p');p.textContent=t;d.appendChild(p);return d}
function scrollEnd(){requestAnimationFrame(function(){chatMsgs.scrollTop=chatMsgs.scrollHeight})}
function vvFit(){
 if(!CHAT.a||!window.visualViewport)return;
 var v=window.visualViewport;chatEl.style.height=v.height+'px';chatEl.style.top=v.offsetTop+'px';scrollEnd();
}
function openChat(a){
 if(CHAT.a===a)return;
 if(CHAT.a)closeChat(true);
 CHAT.a=a;CHAT.token++;
 if(!chatEl.classList.contains('open'))CHAT.back=document.activeElement;
 a.chat=true;a.el.classList.add('sel','chatting');
 if(a.path)pose(a,'idle');
 hush(a);
 $('chatName').textContent=a.n;$('chatRole').textContent=a.r;$('chatSt').textContent='online, '+estado(a);
 ['c','sk','hc'].forEach(function(k){chatAv.style.setProperty('--'+k,a[k])});
 chatIn.placeholder='Fale com '+a.n+'...';chatIn.value='';
 push(a,'ag',greet(a));
 chatMsgs.innerHTML='';
 HIST[a.id].forEach(function(m){chatMsgs.appendChild(bubble(m.f,m.t))});
 chatEl.classList.add('open');document.body.classList.add('noscroll');
 vvFit();scrollEnd();
 if(window.matchMedia&&matchMedia('(hover:hover) and (pointer:fine)').matches)setTimeout(function(){chatIn.focus()},60);
}
function closeChat(keepOpen){
 var a=CHAT.a;if(!a)return;
 CHAT.a=null;CHAT.token++;
 a.chat=false;a.el.classList.remove('sel','chatting');
 if(a.path)pose(a,'walk');
 if(keepOpen)return;
 chatEl.classList.remove('open');document.body.classList.remove('noscroll');
 chatEl.style.height='';chatEl.style.top='';
 if(CHAT.back&&CHAT.back.focus){try{CHAT.back.focus()}catch(_){}}
}
chatForm.addEventListener('submit',function(e){
 e.preventDefault();
 var v=chatIn.value.trim(),a=CHAT.a,tok=CHAT.token;
 if(!v||!a)return;
 chatIn.value='';
 push(a,'me',v);chatMsgs.appendChild(bubble('me',v));scrollEnd();
 CHAT.chain=CHAT.chain.then(function(){
  if(tok!==CHAT.token){push(a,'ag',reply(a,v));return}
  var ty=document.createElement('div');ty.className='msg ag typing';
  ty.innerHTML='<p><span>digitando</span><i></i><i></i><i></i></p>';
  chatMsgs.appendChild(ty);scrollEnd();
  return sleep(rand(800,1500)).then(function(){
   if(ty.parentNode)ty.parentNode.removeChild(ty);
   var r=reply(a,v);push(a,'ag',r);
   if(tok===CHAT.token){chatMsgs.appendChild(bubble('ag',r));scrollEnd()}
  });
 }).catch(function(){});
});
$('chatX').addEventListener('click',function(){closeChat()});
chatEl.addEventListener('click',function(e){if(e.target===chatEl)closeChat()});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&CHAT.a)closeChat()});
if(window.visualViewport){window.visualViewport.addEventListener('resize',vvFit);window.visualViewport.addEventListener('scroll',vvFit)}

