 function step(){
  if(i>=(shot?1:figs.length)){console.log('TEST '+JSON.stringify(out));return}
  var k=shot?4:i;
  figs[k].dispatchEvent(new MouseEvent('click',{bubbles:true}));
  var inp=document.getElementById('chatIn'),f=document.getElementById('chatForm');
  var msgs=shot?['oi, tudo bem?','o que você está fazendo?']:['oi','o que você faz?','como está o trabalho?','valeu','me fala do cuidar.vc','banana azul','banana azul','banana azul','tchau'];
  msgs.forEach(function(m){inp.value=m;f.requestSubmit()});
  setTimeout(function(){
   var bs=[].map.call(document.querySelectorAll('#chatMsgs .msg p'),function(p){return p.textContent});
   out.push({n:document.getElementById('chatName').textContent,ph:inp.placeholder,sel:figs[k].parentNode.classList.contains('sel'),hist:0,msgs:bs});
   i++;step();
  },msgs.length*1600);
 }
 step();
},4000);
</script>
</body>'''
